"""te id"""
from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import range, object
from time import sleep
from future import standard_library
import paramiko
import re
from taf.ul.trs_e2e_fw.lib.call_utils.exceptions import TEIDNotGeneratedException
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()
standard_library.install_aliases()

MAX_RETRIES = 30


class TeId(object):
    """
        Class for TE_ID verification operations
    """
    def __init__(self, dut, rat):
        """
        Initializes class variables
        Args:
            dut(string): The DUT name according to testline config
            rat(string): The Radio Technology
        """
        self.dut = dut
        self.rat = rat
        self.config = ConfigHandler.get_config()
        self.remote_conn = RemoteConnection()

    def get_te_id(self):
        """
        Gets the TEID count from the given DUT

        Returns: int. The count of IWF connections
        """
        bts_params = get_config_variable([self.dut])
        bts_ip = get_config_variable([self.dut, 'ip'])
        bts_user = get_config_variable([self.dut, 'user'])
        bts_password = get_config_variable([self.dut, 'password'])
        bts_port = 22
        if bts_params.get('remote_lmp_ip'):
            remote_lmp_ip = get_config_variable([self.dut, 'remote_lmp_ip'])
            remote_lmp_user = get_config_variable([self.dut, 'remote_lmp_user'])
            remote_lmp_password = get_config_variable([self.dut, 'remote_lmp_password'])
            self.remote_conn.create_ssh_tunnel(remote_lmp_ip, 22, remote_lmp_user, remote_lmp_password, bts_ip,
                                               22, '0.0.0.0', 10022)
            bts_ip = '0.0.0.0'
            bts_port = 10022
            iwf_count = self._get_iwf_connections_count(bts_ip, bts_port, bts_user, bts_password)
            self.remote_conn.stop_ssh_tunnel()
            return iwf_count
        else:
            return self._get_iwf_connections_count(bts_ip, bts_port, bts_user, bts_password)

    def check_iwf_value_increased(self, initial_iwf_value):
        """
        Checks if IWF entries have increased.
        Args:
            initial_iwf_value: Initial IWF entries count.

        Returns:

        """
        for attempt in range(MAX_RETRIES):
            logger.info('Checking TEID increased: Attempt {}'.format(attempt))
            final_iwf_value = self.get_te_id()
            if final_iwf_value <= initial_iwf_value:
                sleep(2)
            else:
                logger.info('TE ID Generated')
                return
            if attempt == MAX_RETRIES - 1:
                raise TEIDNotGeneratedException(self.rat)
            # pass

    def _get_iwf_command(self):
        """
        Gets the IWF command for given bts_hw_version and the RAT.

        Returns: String. The command to get IWF entries count
        """
        if get_config_variable(['bts_hw_version']) == 'fsmr3':
            if self.rat == 'lte':
                return '/opt/trs/bin/secfg_test iptest_ipgw_test_lte_syscom' \
                       '_iwf_uplink_connection_dump \n cat /tmp/lte*'
            elif self.rat == 'wcdma':
                return '/opt/trs/bin/FPCiTest iptest_ipgw_test_wcdma_syscom' \
                       '_iwf_uplink_connection_dump \n cat /tmp/wcdma*'
        elif get_config_variable(['bts_hw_version']) == 'fsmr4':
            if self.rat == 'lte':
                return '/opt/trs/bin/vtc iwf dump table-ul \n cat /tmp/iwf*'
            elif self.rat == 'wcdma':
                return 'cd /opt/trs/bin; ./vtc iwf wcdma dump table-dl;' \
                       ' cat /tmp/iwf_wcdma_dl_table'

    def _get_iwf_connections_count(self, bts_ip, bts_port, bts_user, bts_password):
        """
        1. Connects over SSH to the given IP
        2. Runs IWF command
        Args:
            bts_ip:
            bts_port:
            bts_user:
            bts_password:

        Returns: Int. The IWF connections count.

        """
        ssh_session = paramiko.SSHClient()
        ssh_session.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        ssh_session.connect(hostname=bts_ip, port=bts_port, username=bts_user, password=bts_password)
        (stdin, console_output, stderr) = ssh_session.exec_command(self._get_iwf_command())
        # logger.debug('Stdin: {0}\nConsole output: {1}\nStderr: {2} '.format(stdin, console_output, stderr))
        console_output = decode_str(console_output.read())
        ssh_session.close()
        regex = ''
        logger.info("Console output:\n {}".format(console_output))
        if get_config_variable(['bts_hw_version']) == 'fsmr3':
            if self.rat == 'lte':
                regex = r"Total\s*number\s*of\s*connections\s*in\s*LTE\s*IWF\s*Uplink\s*table\:\s*(\d+)"
            elif self.rat == 'wcdma':
                regex = r"Total\s*number\s*of\s*connections\s*in\s*WCDMA\s*IWF\s*Uplink\s*table\:\s*(\d+)"
        elif get_config_variable(['bts_hw_version']) == 'fsmr4':
            if self.rat == 'lte':
                regex = r"Total\s*number\s*of\s*connections\s*in\s*LTE\s*IWF\s*Uplink\s*table\:\s*(\d+)"
            elif self.rat == 'wcdma':
                regex = r"Total\s*number\s*of\s*IUB_IP->SRIO\s*connections:\s*(\d+)"
        return re.findall(regex, console_output)[0]
